// ===============================================
// Split transcript into 100-line chunks
// Passes config keys forward so nodes can use them
// ===============================================
const text = $input.first().json.data || '';
const config = $('⚙️ Config (Edit These!)').item.json;

const lines = text.split('\n').filter(l => l.trim() !== '');
const chunkSize = 100;
const chunks = [];

for (let i = 0; i < lines.length; i += chunkSize) {
  chunks.push({
    json: {
      chunkIndex: Math.floor(i / chunkSize),
      totalChunks: Math.ceil(lines.length / chunkSize),
      content: lines.slice(i, i + chunkSize).join('\n'),
      OPENAI_API_KEY: config.OPENAI_API_KEY,
      BOT_TOKEN: config.BOT_TOKEN,
      chat_id: config.chat_id,
      file_name: config.file_name
    }
  });
}

console.log(`Lines: ${lines.length} | Chunks: ${chunks.length}`);
return chunks;

// ===============================================
// Combine all translated chunks + create .txt binary
// ===============================================
const items = $input.all();
const firstItem = items[0].json;

// Combine all chunk outputs in order
const fullText = items
  .map(item => {
    const content = item.json?.choices?.[0]?.message?.content;
    if (!content) {
      console.warn('Empty chunk response detected!');
      return '';
    }
    return content.trim();
  })
  .join('\n\n');

// Get timestamp for filename
const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);
const originalName = firstItem.file_name?.replace('.docx', '') || 'transcript';
const fileName = `${originalName}_translated_${timestamp}.txt`;

// Convert to base64 for binary upload
const base64Content = Buffer.from(fullText, 'utf-8').toString('base64');

console.log(`Combined ${items.length} chunks. Final file: ${fileName}`);

return [{
  json: {
    text: fullText,
    chat_id: firstItem.chat_id,
    BOT_TOKEN: firstItem.BOT_TOKEN,
    fileName: fileName
  },
  binary: {
    data: {
      data: base64Content,
      mimeType: 'text/plain; charset=utf-8',
      fileName: fileName,
      fileExtension: 'txt'
    }
  }
}];

